	@Test
	public void tupleQueryCarriesTheResultCacheRequestWhileTheSailEvaluatesIt() {
		List<Boolean> requested = new ArrayList<>();
		when(sailConnection.prepareQuery(any(), eq(Query.QueryType.TUPLE), any(), any())).thenReturn(Optional.empty());
		when(sailConnection.evaluate(any(), any(), any(), anyBoolean())).thenAnswer(invocation -> {
			requested.add(SlowQueryContextHolder.get().isResultCacheRequested());
			return new EmptyIteration<>();
		});

		SailTupleQuery query = (SailTupleQuery) subject.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o }");
		query.evaluate().close();
		query.setLmdbResultCacheRequested(true);
		query.evaluate().close();

		assertThat(requested).containsExactly(false, true);
		assertThat(SlowQueryContextHolder.get()).isNull();
	}

